cd /workspace/project && python3 - <<'EOF'
from plugins.base import PluginError, Plugin
from plugins.csv_plugin import CsvPlugin
from plugins.csv_fields import split_cells

p = CsvPlugin()
assert isinstance(p, Plugin)

# supports
for src, exp in [("csv", True), ("json", False), ("JSON", False), (None, False), (1, False), (b"csv", False), ("", False)]:
    r = p.supports(src)
    assert r is exp, (src, r)

# parse / quoting
assert p.parse('a,"x,y"') == [{"key": "a", "value": "x,y"}], p.parse('a,"x,y"')
assert p.parse('a,1') == [{"key": "a", "value": "1"}]
assert p.parse('a,1\n\n  \nb,"x,y"\n') == [{"key": "a", "value": "1"}, {"key": "b", "value": "x,y"}]
assert p.parse('"k,1","v,2"') == [{"key": "k,1", "value": "v,2"}]
assert p.parse('') == []
assert p.parse('a,1\r\nb,2') == [{"key":"a","value":"1"},{"key":"b","value":"2"}]

# rejections
for bad in ["lonely", 'a,"x,y', '"abc', 'a,"b"c,d"']:
    try:
        p.parse(bad)
        raise AssertionError("expected PluginError for %r" % (bad,))
    except PluginError:
        pass
for bad in [None, 5, b"a,1", ["a,1"]]:
    try:
        p.parse(bad)
        raise AssertionError("expected PluginError for payload %r" % (bad,))
    except PluginError:
        pass

# transform
assert p.transform({"key": " A ", "value": " v "}) == {"key": "A", "value": "v"}
assert p.transform({"key": " A ", "value": " v "}, {"lowercase": True}) == {"key": "a", "value": "v"}
assert p.transform({"key": " A ", "value": " V "}, {"lowercase": False}) == {"key": "A", "value": "V"}
assert p.transform({"key": " A ", "value": " V "}, None) == {"key": "A", "value": "V"}
assert p.transform({"key": " A ", "value": " V "}, "lowercase") == {"key": "A", "value": "V"}
assert p.transform({"key": 12, "value": 3.5}) == {"key": "12", "value": "3.5"}
assert p.transform({"key": None, "value": None}) == {"key": "None", "value": "None"}
for bad in [{"key": "a"}, {"value": "b"}, {}, None, 7, ["a", "b"], "ab"]:
    try:
        p.transform(bad)
        raise AssertionError("expected PluginError for record %r" % (bad,))
    except PluginError:
        pass

# split_cells direct
assert split_cells('a,"x,y"') == ["a", "x,y"]
assert split_cells('a, b ') == ["a", "b"]
print("ALL SMOKE CHECKS PASSED")
EOF
